const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();
const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');

const body = $input.first().json.body || {};
const contractId = parseInt(body.contract_id, 10);
if (!Number.isInteger(contractId)) throw new Error('"contract_id" must be an integer.');
const ownerFieldId = String(body.owner_field_id || '').trim();
if (!ownerFieldId) throw new Error('"owner_field_id" is required.');
const signatureData = String(body.signature_data || '').trim();
if (!signatureData) throw new Error('"signature_data" is required.');
// Any other owner-role fields (e.g. a date next to the signature) the
// countersigner filled in on the same document — merged into
// field_values alongside the signature so they land the same way the
// client's own field_values do at sign time.
const fieldValues = (body.field_values && typeof body.field_values === 'object') ? body.field_values : {};

return [{ json: { requesterId: parseInt(match[1], 10), contractId, ownerFieldId, signatureData, fieldValues } }];

const row = $input.item.json;
const requester = $('Look Up Requester (Cosign)').first().json;
const { ownerFieldId, signatureData, fieldValues } = $('Parse Token & Payload (Cosign)').first().json;

if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (!row.id) throw new Error('Contract not found.');
if (requester.role !== 'admin' && row.assigned_user !== requester.id) throw new Error('You do not have access to this deal.');
if (!row.signed_at) throw new Error('This contract has not been signed by the client yet.');
if (row.cosigned_at) throw new Error('This contract has already been countersigned.');

// The countersignature represents the deal's assigned owner (matches
// the {{owner_name}} merge token already printed in the document body,
// e.g. "Apex Roofing Representative: Juan Smith") — always attributed
// to them even when an admin is the one physically clicking Countersign
// on their behalf, so the audit trail never disagrees with the document
// text. Falls back to the acting admin only if the deal somehow has no
// assigned owner.
const cosignedBy = row.assigned_user || requester.id;

return [{ json: { contractId: row.id, cosignedBy, ownerFieldId, signatureData, fieldValues: JSON.stringify(fieldValues || {}) } }];

parameters.query:
UPDATE contracts SET cosign_signature_data = $1, cosigned_by = $2, cosigned_at = now(),
  field_values = (jsonb_set(COALESCE(field_values, '{}'::jsonb), ARRAY[$3], to_jsonb($1::text)) || $5::jsonb)
WHERE id = $4 AND cosigned_at IS NULL RETURNING id;

